        $stmt = $this->db->prepare($sql);
        $stmt->execute(['username' => $username]);
        $result = $stmt->fetch();

        if ($result && password_verify($password, $result['password_hash'])) {
            return true; // Password is valid
        }

        return false; // Invalid username or password
    }
}
